// The register code's forms no other test reaches: names, registers,
// jumps, operands and cache sites past what an instruction's 16 bits or
// 8 bits number, which test262's programs never come near; a stack trace
// through register frames; f.arguments with Node's quirks; an endless
// chain of tail calls stopped by its context. Each program's answers are
// those the stack interpreter and the tree tier gave, the tiers the
// register interpreter replaced (regFormsWant).

// regForms evaluates src in a new runtime and then each of calls, and fails
// where an answer -- a call's value as a string, or "error: " and its
// error's -- is not the one regFormsWant has for the case name. It returns
// how many functions were given register code. With QJS_REGFORMS_RECORD
// naming a file, it appends the answers there instead, a line of JSON a
// case.
func regForms(t *testing.T, name, src string, calls []string) int64 {
	t.Helper()
	rt := quickjs.New()
	defer rt.Close()
	before := vm.RegsBuilt()
	if _, err := rt.Eval(src); err != nil {
		t.Fatalf("eval: %v", err)
	}
	got := make([]string, len(calls))
	for i, c := range calls {
		v, err := rt.Eval(c)
		if err != nil {
			got[i] = "error: " + err.Error()
			continue
		}
		got[i] = v.String()
	}
	built := vm.RegsBuilt() - before
	if path := os.Getenv("QJS_REGFORMS_RECORD"); path != "" {
		b, _ := json.Marshal(map[string]any{"name": name, "answers": got})
		f, err := os.OpenFile(path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
		if err != nil {
			t.Fatal(err)
		}
		fmt.Fprintf(f, "%s\n", b)
		f.Close()
		return built
	}
	want, ok := regFormsWant[name]
	if !ok || len(want) != len(calls) {
		t.Fatalf("%s: %d answers for %d calls", name, len(want), len(calls))
	}
	for i := range calls {
		if got[i] != want[i] {
			t.Errorf("%.100s:\n  got  %.300s\n  want %.300s", calls[i], got[i], want[i])
		}
	}
	return built
}

// TestRegFormsFarNames compares code whose names run past 16 bits, where an
// instruction's name operand is RNameFar and RegCode.FarNames has the
// index: each function, and each script, starts with 65,600 reads of
// globals by typeof, each a name of its own, and only then names what it
// uses -- globals read, written and deleted, sloppy and strict, an object
// literal's keys made at once and one by one, accessors, a class's
// members, private names and super, a with's names, a constant's and an
// assignment target's errors -- and in scripts and indirect eval code that
// declare 65,600 vars first, top-level declarations.
func TestRegFormsFarNames(t *testing.T) {
	t.Parallel()
	if testing.Short() {
		t.Skip("compiles a dozen programs of 65,600 statements")
	}
	// The reads are in a branch never taken: they take their names and run
	// nothing (a global's miss, 65,600 of them a function, had been most of
	// the test's time).
	var fill strings.Builder
	fill.WriteString("if (gNever) {\n")
	for i := 0; i < 65600; i++ {
		fmt.Fprintf(&fill, "typeof f%d;\n", i)
	}
	fill.WriteString("}\n")
	f := fill.String()
	// A script's declarations take its first names: past 16 bits, those
	// after 65,600 others.
	var d strings.Builder
	d.WriteString("var d0")
	for i := 1; i < 65600; i++ {
		fmt.Fprintf(&d, ", d%d", i)
	}
	d.WriteString(";\n")
	decls := d.String()
	src := `
var gA = 1, gD = 2, gNever = 0;
class B { bm() { return "bm" } get bx() { return 10 } }
function n1() {
` + f + `gA = gA + 1; gA += 2; var r = [gA, typeof gZ, typeof gA, delete gD, typeof gD];
	try { gNo } catch (x) { r.push(x.name + ": " + x.message) }
	var k = "kk", ob = {ka: 1, kb: 2}, oc = {[k]: 1, kc: 3, get ga() { return 4 }, set ga(v) { this.kv = v }}, od = {...ob, kd: 5};
	oc.ga = 6;
	r.push(JSON.stringify(ob), JSON.stringify(oc), oc.ga, JSON.stringify(od));
	const cc = 1;
	try { cc = 2 } catch (x) { r.push(x.name + ": " + x.message) }
	try { n1() = 1 } catch (x) { r.push(x.name + ": " + x.message) }
	return r.join(" | ");
}
function n2() {
	"use strict";
` + f + `var r = []; gA = 7; r.push(gA);
	try { gU = 1 } catch (x) { r.push(x.name + ": " + x.message) }
	try { gV += 1 } catch (x) { r.push(x.name + ": " + x.message) }
	try { gW = String(r.length) } catch (x) { r.push(x.name + ": " + x.message) }
	gA = String(gA + 1); r.push(gA);
	return r.join(" | ");
}
function n3() {
` + f + `class K extends B { #p = 1; static sm() { return "sm" } get kg() { return 2 } set kg(v) { this.q = v } m() { return this.#p } }
	var k = new K(); k.kg = 3;
	return [K.sm(), k.kg, k.q, k.m(), k.bm(), Object.getOwnPropertyNames(K.prototype).join("/")].join();
}
class C2 extends B {
	#p = 1;
	m() {
` + f + `this.#p += 1; super.by = 5; return [this.#p, super.bx, super.bm(), this.by, #p in this].join();
	}
	n(o) {
` + f + `try { return this.#p } catch (x) { return x.name } finally { try { C2.prototype.m.call(o) } catch (x) { globalThis.pe = x.name + ": " + x.message } }
	}
}
function n4(o) {
` + f + `with (o) { wx = wx + 1; wn = 9; return [wx, wy, typeof wz, wn].join() }
}
`
	calls := []string{`n1()`, `n2()`, `n3()`, `new C2().m()`, `new C2().n({}) + " " + pe`,
		`var wo = {wx: 1, wy: 2, wn: 0}; n4(wo) + " " + wo.wx + " " + wo.wn`,
		f + `var tv = 1; let tl = 2; const tc = 3; function tf() { return 4 } class tk {} tv + tl + tc + tf() + typeof tk`,
		`tv + tl + tc + tf() + typeof tk`,
		`(0, eval)(` + "`" + f + "var iv = 5; let il = 6; iv + il`" + `) + "," + iv + "," + typeof il`,
		decls + `let dl = 1; const dc = 2; function dfn() { return 3 } class dk {} d65599 = 4; d65599 + dl + dc + dfn() + typeof dk`,
		`(0, eval)(decls + "var dv = 5; d1 = dv; d1")`,
		`(function () { return eval(` + "`" + f + "var dv = 7; let dl = 8; dv + dl + gA`" + `) + "," + dv })()`}
	if built := regForms(t, "FarNames", src, calls); built == 0 {
		t.Errorf("no function is register code")
	}
}

// TestRegFormsFarRegisters compares functions whose bindings do not fit
// 16 bits of registers, where those used least have far ones, reached by
// mov_far and mov_to_far alone: each declares 65,600 bindings used five
// times, and only then those the cases use, five times or fewer, which
// are far (farSlots). Reads, stores, compound assignments and updates,
// appends, patterns, for-in and for-of heads, a loop's counter, let and
// const, typeof, a closure over a near binding beside them, the
// arguments object, a generator suspended with its far bindings, and a
// named function expression's own name; and a function whose bindings fit
// but leave its temporaries too few registers.
func TestRegFormsFarRegisters(t *testing.T) {
	t.Parallel()
	if testing.Short() {
		t.Skip("compiles functions of 65,600 bindings three times")
	}
	var fill strings.Builder
	for i := 0; i < 65600; i++ {
		fmt.Fprintf(&fill, "var v%d = v%d + v%d + v%d + v%d;\n", i, i, i, i, i)
	}
	f := fill.String()
	// A function whose 30,000 bindings fit, but not beside the 40,000
	// temporaries of a template's 40,000 parts: compiled again with a
	// quarter of the registers for its bindings (nearCap).
	var deep strings.Builder
	deep.WriteString("function deep(p) {\n" + f[:strings.Index(f, "var v30000 ")] + "var x = p, y = p + 1;\n\treturn `" + strings.Repeat("${x}-", 19999) + "${y}`;\n}\n")
	src := deep.String() + `
function big(p) {
` + f + `var r = [];
	var a1 = 5; r.push(a1, typeof a1);
	var a2; a2 = p * 2; r.push(a2);
	var a3 = 1; a3 += p; r.push(a3);
	var a4 = 1; a4++; r.push(a4);
	var a5 = 1; r.push(--a5);
	var a6 = 1; r.push(a6++, a6);
	var s = ""; s += "x"; s += "y";
	var [d1, d2] = [1, 2]; var d3; ({d3} = {d3: 3}); r.push(s, d1, d2, d3);
	for (var k in {m: 1, n: 2}) r.push(k);
	for (var e of [7, 8]) r.push(e);
	var t = 0; for (var i = 0; i < 4; i++) t += i;
	r.push(t);
	let l1 = 4; const c1 = 6; r.push(l1 + c1);
	var cap = 1; var get = () => cap; cap = 2; r.push(get());
	r.push(arguments.length, arguments[0]);
	var o = {q: 9}; var q = o.q; r.push(q);
	return r.join();
}
function* gen(p) {
` + f + `var x = p; yield x; x = x + 1; yield x;
	var y = yield x * 10; yield y;
}
var named = function self(p) {
` + f + `var z = p + 1;
	return typeof self + z;
};
`
	calls := []string{`deep(2)`, `big(3)`, `big(-1)`, `var g = gen(5); [g.next().value, g.next().value, g.next().value, g.next(42).value, g.next().done].join()`, `named(1)`}
	if built := regForms(t, "FarRegisters", src, calls); built == 0 {
		t.Errorf("no function is register code")
	}
}

// TestRegFormsFarJumps compares functions with jumps past a 16-bit offset,
// compiled again with every such jump far: an if and an else over long
// bodies, a loop's test and its backward jump, a break and a continue out
// of one, a logical operator and a conditional around one, a switch, and a
// throw's position past them.
func TestRegFormsFarJumps(t *testing.T) {
	t.Parallel()
	body := strings.Repeat("a = a + 1 | 0; ", 20000)
	src := `
var frames = function (e) { return e.name + ": " + e.message + " | " + e.stack.split("\n").slice(1, 3).map(function (s) { return s.trim() }).join(" | ") };
function j1(x) { var a = 0; if (x) { ` + body + ` } else { ` + body + ` a = -a } return a }
function j2(n) { var a = 0, k = 0; for (var i = 0; i < n; i++) { if (i == 2) continue; if (i == 5) break; ` + body + ` k++ } return a + ":" + k }
function j3(x) { var a = 0; var r = x && (function () { ` + body + ` return a })(); return x ? r : (function () { ` + body + ` return -a })() }
function j4(x) { var a = 0; switch (x) { case 1: ` + body + ` break; case 2: a = 7; default: a += 1 } return a }
function j5(x) { var a = 0; while (true) { ` + body + ` if (a > x) throw new Error("j5 " + a) } }
`
	calls := []string{
		`j1(true)`, `j1(false)`, `j2(9)`, `j2(1)`, `j3(1)`, `j3(0)`, `j4(1)`, `j4(2)`, `j4(3)`,
		`try { j5(30000) } catch (e) { frames(e) }`,
	}
	regForms(t, "FarJumps", src, calls)
}

// TestRegFormsWide compares what an instruction's operands cannot
// number, made as wide forms: calls of more than 255 arguments -- plain,
// a method's, an optional chain's, new, super(), a tagged template's, a
// direct eval's --, spread calls through an optional chain, array
// literals past one instruction's elements, and functions with more
// cache sites than 16 bits number, their sites shared.
func TestRegFormsWide(t *testing.T) {
	t.Parallel()
	var args, holes, consts strings.Builder
	for i := 0; i < 300; i++ {
		if i > 0 {
			args.WriteString(", ")
		}
		fmt.Fprintf(&args, "i + %d", i)
	}
	for i := 0; i < 3000; i++ {
		if i%7 == 3 {
			holes.WriteString(", ")
			continue
		}
		fmt.Fprintf(&holes, "i * %d, ", i)
	}
	for i := 0; i < 70000; i++ {
		fmt.Fprintf(&consts, "%d,", i%97)
	}
	var sites, callSites strings.Builder
	// 20,000 reads and as many writes: 40,000 sites, past 16 bits,
	// shared. 70,000 calls of a local:
	// call sites past 16 bits, and no property site.
	for i := 0; i < 20000; i++ {
		fmt.Fprintf(&sites, "s += o.p%d; o.q%d = s; ", i%5, i%3)
	}
	for i := 0; i < 70000; i++ {
		fmt.Fprintf(&callSites, "s += hl(%d); ", i%11)
	}
	a := args.String()
	tmpl := strings.Repeat("${i}-", 300)
	src := `
var frames = function (e) { return e.name + ": " + e.message + " | " + e.stack.split("\n").slice(1, 3).map(function (s) { return s.trim() }).join(" | ") };
function count() { return arguments.length + ":" + arguments[0] + ":" + arguments[arguments.length - 1] }
var obj = { m: function () { return (this === obj) + count.apply(null, arguments) } };
function w1(i) { return count(` + a + `) }
function w2(i) { return obj.m(` + a + `) }
function w3(i, o) { return o?.m(` + a + `) }
function w4(i) { function C() { this.n = arguments.length + arguments[299] } return new C(` + a + `).n }
class B { constructor() { this.n = arguments.length + ":" + arguments[299] } }
class D extends B { constructor(i) { super(` + a + `) } }
function w5(i) { return new D(i).n }
function tag(s) { return s.length + ":" + arguments.length + ":" + arguments[300] }
function w6(i) { return tag` + "`" + tmpl + "`" + ` }
function w7(i) { return eval("i + 1", ` + a + `) }
function w8(o, xs) { return o?.m(...xs) }
function w9(o, xs) { return (o?.m)(...xs) }
function w10(i) { var a = [` + holes.String() + `]; return a.length + ":" + a[2999] + ":" + (3 in a) + ":" + a[2996] }
function w11() { var a = [` + consts.String() + `]; a[5] = "w"; return a.length + ":" + a[69999] + ":" + a[5] }
function w12(o) { var s = 0; ` + sites.String() + ` return s + ":" + o.q2 }
function h(k) { return k }
function w13() { var s = 0, hl = h; ` + callSites.String() + ` return s }
function w14(i) { return count(` + a + `, oops.x) }
var wo = { v: 9, m(x) { return (this === wo) + ":" + this.v + ":" + x + ":" + arguments.length } };
function plain() { return this === globalThis }
function w15(i, o) { with (o) { return m(...[i, 2]) + "/" + m(` + a + `) + "/" + plain(...[]) } }
function w16(o) { with (o) { return m(...[1]) } }
`
	calls := []string{
		`w1(1)`, `w2(1)`, `w3(1, obj)`, `w3(1, null)`, `w4(2)`, `w5(3)`, `w6(4)`, `w7(5)`,
		`w8(obj, [1, 2])`, `w8(undefined, [1])`, `w9(obj, [3])`, `try { w9(null, []) } catch (e) { frames(e) }`,
		`w10(2)`, `w11() + w11()`,
		`w12({ p0: 1, p1: 2, p2: 3, p3: 4, p4: 5 })`, `w12({ get p0() { return 1 }, p1: 1 })`,
		`w13()`,
		`try { w14(1) } catch (e) { frames(e) }`,
		`w15(1, wo)`, `try { w16({}) } catch (e) { frames(e) }`,
	}
	regForms(t, "Wide", src, calls)
}

// TestRegFormsSitesPast16Bits compares functions with more cache sites
// than 16 bits number, compiled again with the sites of one key shared:
// property reads and writes,
// method calls, global reads and writes, strict code's global store,
// instanceof, object literals and an array literal of constants, read
// polymorphically, and a throw's position past them all.
func TestRegFormsSitesPast16Bits(t *testing.T) {
	t.Parallel()
	var sloppy, strict strings.Builder
	for i := 0; i < 36000; i++ {
		fmt.Fprintf(&sloppy, "s += o.p%d; o.q%d = s;\n", i%5, i%3)
	}
	for i := 0; i < 34000; i++ {
		fmt.Fprintf(&strict, "gs = gs + o.p%d;\n", i%4)
	}
	src := `
var frames = function (e) { return e.name + ": " + e.message + " | " + e.stack.split("\n").slice(1, 3).map(function (s) { return s.trim() }).join(" | ") };
var gv = 1, gs = 0;
function C() {}
function w1(o) {
var s = gv;
` + sloppy.String() + `
var lit = { a: s, b: o.p0 }, arr = [1, 2, 3], m = o.m ? o.m(2) : 0;
gv = gv + 1;
return s + ":" + o.q2 + ":" + lit.a + lit.b + ":" + arr.join() + ":" + (o instanceof C) + ":" + m + ":" + gv + ":" + o.r.x;
}
function w2(o) {
"use strict";
` + strict.String() + `
gs = gs + 1; undeclared = gs;
return gs;
}
`
	calls := []string{
		`try { w1({ p0: 1, p1: 2, p2: 3, p3: 4, p4: 5, r: { x: 7 } }) } catch (e) { frames(e) }`,
		`try { var c = new C(); c.p0 = 2; c.m = function (x) { return x * this.p0 }; c.r = { x: 8 }; w1(c) } catch (e) { frames(e) }`,
		`try { w1({ get p0() { return 1 }, p1: 1 }) } catch (e) { frames(e) }`,
		`try { w2({ p0: 1, p1: 1, p2: 1, p3: 1 }) } catch (e) { frames(e) }`,
		`try { undeclared = 0; w2({ p0: 1, p1: 1, p2: 1, p3: 1 }) } catch (e) { frames(e) }`,
	}
	regForms(t, "SitesPast16Bits", src, calls)
}

// TestRegFormsRegExpWideConstants compares RegExp literals' calls in a
// function whose literals' constants are past 16 bits, which lit_exec_call
// and lit_exec cannot name in their words: the calls are made through the
// literal's own instruction and call_method_w's Aux, all 32 bits of it.
func TestRegFormsRegExpWideConstants(t *testing.T) {
	t.Parallel()
	var b strings.Builder
	b.WriteString("function wide(s) {\n\tvar x, out = [];\n")
	for i := 0; i < 70000; i++ {
		fmt.Fprintf(&b, "\tx = \"c%d\";\n", i)
	}
	b.WriteString("\tfor (var j = 0; j < 3; j++) out.push(/q/.test(s), /(q)/.exec(s)[1], s.replace(/q/g, x), s.split(/u/).length, /a/.exec(\"za\").index);\n\treturn out.join();\n}\n")
	built := regForms(t, "RegExpWideConstants", b.String(), []string{`wide("uqu")`, `wide("q")`})
	if built == 0 {
		t.Errorf("wide is not register code")
	}
}

// TestRegFormsStacksAndNames compares what a stack trace says of register
// frames -- each call's position, its function's name, whether it is a
// construct, its receiver's type -- after the call sites' caches are warm,
// and the names a function's body resolves: its own name shadowed in a
// block, the arguments object an apply other than the built-in is given.
func TestRegFormsStacksAndNames(t *testing.T) {
	t.Parallel()
	src := `
function frames(e) { return e.stack.split("\n").slice(1).map(function (s) { return s.trim() }).join(" | ") }
function thrower() { return null.x }
function calls(n) { return n > 0 ? calls(n - 1) + 1 : thrower() }
function made() { return new Error("m") }
function viaArrow() { return (() => made())() }
function L() { return Error.call(this) }
function M() { this.e = made() }
var o = { m: function () { return made() }, n: function named() { return made() } };
function Foo() {} Foo.prototype.m = function () { return made() };
var a = {}; a.b = function () { return made() };
function self() { return (function g() { { let g = 1 } return typeof g })() }
function selfVar() { return (function g() { var g; return typeof g })() }
function own(a) { var f = { apply: function (t, args) { return args } }; var x = f.apply(null, arguments); a = 2; var y = f.apply(null, arguments); return [x === y, x[0], x.length] }
function warm(f) { for (var i = 0; i < 4; i++) f() }
function stackOf(f) { try { var v = f(); return v && v.stack ? frames(v) : String(v) } catch (e) { return frames(e) } }
`
	var calls []string
	for _, f := range []string{
		"function () { return calls(3) }",
		"made", "viaArrow", "function () { return new L() }", "function () { return new M().e }",
		"function () { return o.m() }", "function () { return o.n() }", "function () { return new Foo().m() }",
		"function () { return a.b() }", "self", "selfVar", "function () { return own(1, 2) }",
	} {
		calls = append(calls, fmt.Sprintf("(function () { var f = %s; warm(function () { try { f() } catch (e) {} }); return stackOf(f) })()", f))
	}
	regForms(t, "StacksAndNames", src, calls)
}

// TestRegFormsLegacyArguments compares a sloppy function's f.arguments
// (WithNodeQuirks) in frames register code makes: the count, which the
// caller's call instruction holds, and the arguments past the parameters,
// which the callee's bindings overwrite in its window -- through a site's
// first call, its cached callee, a method call, a tail call, a callback,
// call, apply and a bound function, and a forwarder -- and a parameter a
// closure captures or of a list with a default, read as passed.
func TestRegFormsLegacyArguments(t *testing.T) {
	src := `
function f(a) { var x = 7, y = 8; return f.arguments.length + ":" + [...f.arguments].join() + ":" + (x + y) }
function f2(a, b) { var t = a * 2; return [...f2.arguments].join() + "|" + t }
function none() { var q = 1, w = 2; return none.arguments.length + q + w }
function g() { var r = []; for (var i = 0; i < 3; i++) r.push(f(1, 2, 3), f(4), f()); return r.join(" ") }
function h() { var o = { m: f2 }, r = []; for (var i = 0; i < 3; i++) r.push(o.m(5, 6, 7, 8), f2(9)); return r.join(" ") }
function k() { var s = 0; for (var i = 0; i < 3; i++) s += none(1, 2, 3, 4) * 10 + none(); return s }
function tl() { "use strict"; return f(i9, 10, 11) }
var i9 = 9;
function deep(n) { return n === 0 ? tl() : deep(n - 1) + "" }
function viaCall() { var r = []; for (var i = 0; i < 3; i++) r.push(f.call(null, 1, 2, 3), f.apply(null, [4, 5]), Reflect.apply(f, null, [6, 7, 8, 9]), f.bind(null, 1)(2, 3)); return r.join(" ") }
function fw() { return f.apply(null, arguments) }
function viaFw() { return fw(1, 2, 3, 4) + " " + fw() }
function cap(a, b) { a = 5; b = 6; var g = () => a + b; return [...cap.arguments].join() + ":" + g() }
function pat(a, b = 2) { a = 7; return [...pat.arguments].join() }
function viaCap() { var r = []; for (var i = 0; i < 3; i++) r.push(cap(1), cap(1, 2, 3), cap.call(null, 4), [8, 9].map(cap).join("/"), pat(1), pat(1, 2, 3), pat.call(null, 4)); return r.join(" ") }
`
	calls := []string{"none(1, 2, 3, 4)", "(function () { return none(1, 2, 3, 4) })()", "(function () { var s = 0; for (var i = 0; i < 3; i++) s += none(1, 2, 3, 4); return s })()", "g()", "h()", "k()", "tl()", "deep(40)", "viaCall()", "viaFw()", "viaCap()", "cap(1, 2)", "g() + h()"}
	run := func() []string {
		rt := quickjs.New(quickjs.WithNodeQuirks())
		defer rt.Close()
		if _, err := rt.Eval(src); err != nil {
			t.Fatalf("eval: %v", err)
		}
		out := make([]string, len(calls))
		for i, c := range calls {
			v, err := rt.Eval(c)
			if err != nil {
				out[i] = "error: " + err.Error()
			} else {
				out[i] = v.String()
			}
		}
		return out
	}
	// The answers the stack interpreter and the tree tier gave.
	want := []string{"7", "7", "21",
		"3:1,2,3:15 1:4:15 0::15 3:1,2,3:15 1:4:15 0::15 3:1,2,3:15 1:4:15 0::15",
		"5,6,7,8|10 9|18 5,6,7,8|10 9|18 5,6,7,8|10 9|18",
		"219", "3:9,10,11:15", "3:9,10,11:15",
		"3:1,2,3:15 2:4,5:15 4:6,7,8,9:15 3:1,2,3:15 3:1,2,3:15 2:4,5:15 4:6,7,8,9:15 3:1,2,3:15 3:1,2,3:15 2:4,5:15 4:6,7,8,9:15 3:1,2,3:15",
		"4:1,2,3,4:15 0::15",
		"1:11 1,2,3:11 4:11 8,0,8,9:11/9,1,8,9:11 1 1,2,3 4 1:11 1,2,3:11 4:11 8,0,8,9:11/9,1,8,9:11 1 1,2,3 4 1:11 1,2,3:11 4:11 8,0,8,9:11/9,1,8,9:11 1 1,2,3 4",
		"1,2:11",
		"3:1,2,3:15 1:4:15 0::15 3:1,2,3:15 1:4:15 0::15 3:1,2,3:15 1:4:15 0::155,6,7,8|10 9|18 5,6,7,8|10 9|18 5,6,7,8|10 9|18",
	}
	before := vm.RegsBuilt()
	on := run()
	if vm.RegsBuilt() == before {
		t.Error("no function was register code")
	}
	for i, c := range calls {
		if want[i] != on[i] {
			t.Errorf("%s: %q, register code %q", c, want[i], on[i])
		}
	}
}

// TestRegFormsTailCallsStop checks that an endless loop of calls in tail
// position, each made in its frame's place (regRestartRun), polls as a
// loop does: the host's context stops it.
func TestRegFormsTailCallsStop(t *testing.T) {
	func() {
		rt := quickjs.New()
		defer rt.Close()
		ctx, cancel := context.WithTimeout(context.Background(), 200*time.Millisecond)
		defer cancel()
		for _, src := range []string{
			`"use strict"; function inf(n) { return inf(n + 1) } inf(0)`,
			`"use strict"; function a(n) { return b(n + 1) } function b(n) { return a(n + 1) } a(0)`,
		} {
			if _, err := rt.EvalContext(ctx, src); err == nil {
				t.Errorf("%s: an endless loop of calls in tail position ended", src)
			}
		}
	}()
}

